PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (user_id TEXT PRIMARY KEY,name TEXT NOT NULL,mobile TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('Farmer','Coordinator','Agricultural Expert','Administrator')),status TEXT NOT NULL DEFAULT 'Registered' CHECK(status IN ('Registered','Active','Inactive')),created_date TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS farmers (user_id TEXT PRIMARY KEY REFERENCES users(user_id) ON DELETE CASCADE,village TEXT,land_area REAL);
CREATE TABLE IF NOT EXISTS coordinators (user_id TEXT PRIMARY KEY REFERENCES users(user_id) ON DELETE CASCADE,bank_name TEXT,location TEXT);
CREATE TABLE IF NOT EXISTS agricultural_experts (user_id TEXT PRIMARY KEY REFERENCES users(user_id) ON DELETE CASCADE,expertise TEXT,organization TEXT);
CREATE TABLE IF NOT EXISTS administrators (user_id TEXT PRIMARY KEY REFERENCES users(user_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS seed_varieties (variety_id TEXT PRIMARY KEY,name TEXT NOT NULL,source TEXT NOT NULL,storage_location TEXT NOT NULL,created_by TEXT REFERENCES users(user_id),created_date TEXT NOT NULL,UNIQUE(name,source,storage_location));
CREATE TABLE IF NOT EXISTS seed_inventories (inventory_id TEXT PRIMARY KEY,variety_id TEXT NOT NULL UNIQUE REFERENCES seed_varieties(variety_id) ON DELETE CASCADE,available_quantity INTEGER NOT NULL DEFAULT 0 CHECK(available_quantity >= 0),low_stock_threshold INTEGER NOT NULL DEFAULT 5,updated_date TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quality_tests (test_id TEXT PRIMARY KEY,variety_id TEXT NOT NULL REFERENCES seed_varieties(variety_id),test_date TEXT NOT NULL,germination REAL NOT NULL CHECK(germination BETWEEN 0 AND 100),purity REAL NOT NULL CHECK(purity BETWEEN 0 AND 100),moisture REAL NOT NULL CHECK(moisture BETWEEN 0 AND 100),status TEXT NOT NULL,review_status TEXT NOT NULL DEFAULT 'NotRequired',tester_id TEXT REFERENCES users(user_id),created_date TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS expert_recommendations (recommendation_id TEXT PRIMARY KEY,expert_id TEXT NOT NULL REFERENCES users(user_id),test_id TEXT REFERENCES quality_tests(test_id),variety_id TEXT REFERENCES seed_varieties(variety_id),type TEXT NOT NULL,content TEXT NOT NULL,recommendation_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Published');
CREATE TABLE IF NOT EXISTS loan_transactions (loan_id TEXT PRIMARY KEY,farmer_id TEXT NOT NULL REFERENCES users(user_id),variety_id TEXT NOT NULL REFERENCES seed_varieties(variety_id),requested_quantity INTEGER NOT NULL CHECK(requested_quantity > 0),issued_quantity INTEGER,outstanding_quantity INTEGER NOT NULL DEFAULT 0 CHECK(outstanding_quantity >= 0),status TEXT NOT NULL DEFAULT 'Pending',purpose TEXT,request_date TEXT NOT NULL,decision_date TEXT,issue_date TEXT,decided_by TEXT REFERENCES users(user_id),rejection_reason TEXT);
CREATE TABLE IF NOT EXISTS seed_returns (return_id TEXT PRIMARY KEY,loan_id TEXT NOT NULL REFERENCES loan_transactions(loan_id) ON DELETE CASCADE,returned_quantity INTEGER NOT NULL CHECK(returned_quantity > 0),return_date TEXT NOT NULL,return_type TEXT NOT NULL,recorded_by TEXT REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS agricultural_queries (query_id TEXT PRIMARY KEY,farmer_id TEXT NOT NULL REFERENCES users(user_id),question TEXT NOT NULL,submitted_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Open',response TEXT,response_date TEXT,expert_id TEXT REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS community_events (event_id TEXT PRIMARY KEY,title TEXT NOT NULL,event_date TEXT NOT NULL,location TEXT NOT NULL,description TEXT NOT NULL,created_by TEXT REFERENCES users(user_id),created_date TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_articles (article_id TEXT PRIMARY KEY,title TEXT NOT NULL,content TEXT NOT NULL,category TEXT NOT NULL,review_status TEXT NOT NULL DEFAULT 'Draft',author_id TEXT REFERENCES users(user_id),reviewer_id TEXT REFERENCES users(user_id),review_note TEXT,created_date TEXT NOT NULL,updated_date TEXT);
CREATE TABLE IF NOT EXISTS otp_codes (otp_id INTEGER PRIMARY KEY AUTOINCREMENT,mobile TEXT NOT NULL,code_hash TEXT NOT NULL,expires_at TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,consumed INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (notification_id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,title TEXT NOT NULL,body TEXT NOT NULL,type TEXT NOT NULL,related_id TEXT,is_read INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stock_ledger (ledger_id TEXT PRIMARY KEY,variety_id TEXT NOT NULL REFERENCES seed_varieties(variety_id),delta INTEGER NOT NULL,resulting_balance INTEGER NOT NULL CHECK(resulting_balance >= 0),reason TEXT NOT NULL,actor_id TEXT REFERENCES users(user_id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS event_participants (event_id TEXT NOT NULL REFERENCES community_events(event_id) ON DELETE CASCADE,farmer_id TEXT NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,registered_at TEXT NOT NULL,PRIMARY KEY(event_id,farmer_id));
CREATE TABLE IF NOT EXISTS article_views (article_id TEXT NOT NULL REFERENCES knowledge_articles(article_id) ON DELETE CASCADE,farmer_id TEXT NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,viewed_at TEXT NOT NULL,PRIMARY KEY(article_id,farmer_id));
CREATE TABLE IF NOT EXISTS processed_requests (idempotency_key TEXT PRIMARY KEY,endpoint TEXT NOT NULL,result TEXT NOT NULL DEFAULT 'OK',processed_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_loans_farmer ON loan_transactions(farmer_id); CREATE INDEX IF NOT EXISTS idx_loans_status ON loan_transactions(status); CREATE INDEX IF NOT EXISTS idx_notif_user ON notifications(user_id,is_read);
